</style></head><body><header class="wrap head"><a class="brand" href="{{ route('home') }}">easy<span>english</span></a><a href="{{ route('home') }}">{{ __('public.back_home') }}</a></header><main class="wrap layout"><section class="intro"><p style="font-size:11px;letter-spacing:1.5px;font-weight:800;color:var(--green)">{{ $type==='intro' ? __('public.booking_intro_label') : __('public.booking_bundle_label') }}</p><h1>{{ $type==='intro' ? __('public.booking_intro_title') : __('public.booking_bundle_title') }}</h1><p>{{ $type==='intro' ? __('public.booking_intro_text') : __('public.booking_bundle_text', ['name'=>$entitlement->definition->name,'credits'=>$entitlement->credits_remaining+$entitlement->free_credits_remaining,'expiry'=>$entitlement->expires_at->setTimezone('Europe/Bucharest')->format('d.m.Y')]) }}</p><div class="panel" data-availability data-week="{{ $weekStart->format('Y-m-d') }}" data-book-url="{{ route('booking.create') }}" data-type="{{ $type }}" @if($entitlement) data-entitlement="{{ $entitlement->id }}" @endif><div style="display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:16px"><h2 style="margin:0">{{ __('public.booking_week_title') }}</h2><div style="display:flex;gap:6px"><button type="button" data-prev aria-label="{{ __('public.previous_week') }}" style="width:34px;height:34px;border:1px solid var(--line);border-radius:50%;background:white;cursor:pointer">‹</button><button type="button" data-next aria-label="{{ __('public.next_week') }}" style="width:34px;height:34px;border:1px solid var(--line);border-radius:50%;background:white;cursor:pointer">›</button></div></div><div class="weekgrid" data-weekgrid><p>{{ __('public.availability_loading') }}</p></div><p class="timezone">{{ __('public.timezone_note') }}</p></div><p><a href="{{ route('home') }}#availability">{{ __('public.back_booking') }}</a></p></section><section><form class="panel" method="post" action="{{ $formAction }}" id="booking-form">@csrf<h2>{{ __('public.booking_details') }}</h2>@if($errors->any())<div class="errors" role="alert">@foreach($errors->all() as $error)<div>{{ $error }}</div>@endforeach</div>@endif<div class="field"><label for="name">{{ __('public.field_name') }}</label><input id="name" name="name" value="{{ old('name') }}" autocomplete="name" required maxlength="160"></div><div class="grid2"><div class="field"><label for="email">{{ __('public.field_email') }}</label><input id="email" name="email" type="email" value="{{ old('email') }}" autocomplete="email" required maxlength="254"></div><div class="field"><label for="phone">{{ __('public.field_phone') }}</label><input id="phone" name="phone" type="tel" value="{{ old('phone') }}" autocomplete="tel" required maxlength="32" pattern="[+0-9 () .-]{7,32}"></div></div><div class="field"><label for="english_level">{{ __('public.field_level') }}</label><select id="english_level" name="english_level" required><option value="">{{ __('public.field_level_placeholder') }}</option>@foreach(['A1','A2','B1','B2','C1','C2'] as $level)<option value="{{ $level }}" @selected(old('english_level')===$level)>{{ __('public.level_'.strtolower($level)) }}</option>@endforeach</select></div><div class="field"><label for="session_goal">{{ __('public.field_goal') }}</label><input id="session_goal" name="session_goal" value="{{ old('session_goal') }}" placeholder="{{ __('public.field_goal_placeholder') }}" required maxlength="500"></div><div class="field"><label for="notes">{{ __('public.field_notes') }}</label><textarea id="notes" name="notes" maxlength="5000" placeholder="{{ __('public.field_notes_placeholder') }}">{{ old('notes') }}</textarea></div><div class="notice">{{ __('public.policy_summary') }} <a href="{{ route('policy','terms') }}">{{ __('public.footer_terms') }}</a> · <a href="{{ route('policy','privacy') }}">{{ __('public.footer_privacy') }}</a></div><label class="check"><input type="checkbox" name="accepted_policy" value="1" required @checked(old('accepted_policy'))><span>{{ __('public.policy_accept') }}</span></label><input type="hidden" name="type" value="{{ $type }}"><input type="hidden" name="starts_at" id="starts_at" value="{{ old('starts_at', request('slot')) }}" required>@if($entitlement)<input type="hidden" name="entitlement" value="{{ $entitlement->id }}">@endif<button class="button" type="submit">{{ $type==='intro' ? __('public.booking_submit_intro') : __('public.booking_submit_bundle') }}</button><p style="font-size:12px;color:var(--muted);line-height:1.5">{{ $type==='intro' ? __('public.verification_required') : __('public.booking_join') }}</p></form></section></main><footer class="wrap foot">{{ __('public.footer_line') }}</footer>
<script>
(()=>{const root=document.querySelector('[data-availability]');const grid=root.querySelector('[data-weekgrid]');let week=root.dataset.week;const selected=document.querySelector('#starts_at');const previous=root.querySelector('[data-prev]');const next=root.querySelector('[data-next]');const today=new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Bucharest'});const monday=d=>{const x=new Date(d+'T12:00:00');x.setDate(x.getDate()-((x.getDay()+6)%7));return x.toLocaleDateString('en-CA')};const add=(date,days)=>{const x=new Date(date+'T12:00:00');x.setDate(x.getDate()+days);return x.toLocaleDateString('en-CA')};const render=days=>{grid.innerHTML='';days.forEach(day=>{const col=document.createElement('div');col.className='day';const head=document.createElement('div');head.className='dayhead';const a=document.createElement('span');a.textContent=day.label;const b=document.createElement('span');b.textContent=day.day;head.append(a,b);const slots=document.createElement('div');slots.className='slots';if(!day.slots.length){const e=document.createElement('span');e.className='empty';e.textContent=@json(__('public.slot_none'));slots.append(e)}else day.slots.forEach(slot=>{const button=document.createElement('button');button.type='button';button.className='slot'+(selected.value===slot.starts_at?' selected':'');button.textContent=slot.time;button.setAttribute('aria-pressed',selected.value===slot.starts_at?'true':'false');button.addEventListener('click',()=>{selected.value=slot.starts_at;grid.querySelectorAll('.slot').forEach(x=>{x.classList.remove('selected');x.setAttribute('aria-pressed','false')});button.classList.add('selected');button.setAttribute('aria-pressed','true')});slots.append(button)});col.append(head,slots);grid.append(col)})};const load=()=>{previous.disabled=week<=monday(today);previous.style.opacity=previous.disabled?'.35':'1';grid.innerHTML='<p>'+@json(__('public.availability_loading'))+'</p>';fetch('{{ route('availability') }}?week='+encodeURIComponent(week),{headers:{Accept:'application/json'}}).then(r=>r.json()).then(data=>render(data.days)).catch(()=>{grid.textContent=@json(__('public.availability_error'))})};previous.addEventListener('click',()=>{if(!previous.disabled){week=add(week,-7);load()}});next.addEventListener('click',()=>{week=add(week,7);load()});load();})();
</script></body></html>
